 string VerifyRelics(){var account=save;bool oldVerify=verifying;int oldHero=heroIndex,oldCurse=selectedCurse,oldDragon=selectedDragon;verifying=true;save=new SaveData();heroIndex=0;selectedCurse=-1;save.NormalizeRelics();GoHome();OpenPowerUp(ScreenState.Menu);EnterPowerUpSection(2);if(state!=ScreenState.Relics)throw new Exception("Relics menu navigation failed");CloseRelics();if(state!=ScreenState.PowerUp)throw new Exception("Relics menu return failed");if(TryEquipRelic(0,0)||EquippedRelic(0,0)!=-1)throw new Exception("Locked relic equipped");StartRun();var boss=SpawnEnemy(3,false);boss.p=pos;Damage(boss,boss.maxHp+1);if(OwnsRelic(0)||!loot.Exists(l=>l.kind==4&&(int)l.value==0))throw new Exception("Boss relic ground drop missing");UpdateLoot(.1f);if(!OwnsRelic(0)||runRelicRewards.Count!=1||runArmor!=-1)throw new Exception("Relic pickup failed");if(!TryEquipRelic(0,0))throw new Exception("Owned armor cannot equip");DropBossRelic(3,pos,false);UpdateLoot(.1f);if(!OwnsRelic(1)||!TryEquipRelic(0,1))throw new Exception("Second guardian reward failed");StartRun();if(maxHp!=130||Mathf.Abs(runRelics.power-1.18f)>.001f||runRelics.set!=0||runArmor!=0||runTalisman!=1)throw new Exception("Relic run stats/curse/set failed");AnimateHero(.1f,Vector2.right);if(!hero.sprite.name.StartsWith("equipment-body-miquella-v28"))throw new Exception("Equipped armor did not reach gameplay animation");float startHp=hp;invincible=dashTimer=0;HurtPlayer(10,true);if(Mathf.Abs(hp-(startHp-9))>.01f)throw new Exception("Armor reduction not applied");save.totalKills=250;heroIndex=1;StartRun();if(runArmor!=-1||runTalisman!=-1||maxHp!=100)throw new Exception("Loadout leaked between heroes");heroIndex=0;UnequipRelic(0,1);StartRun();if(runRelics.set!=-1||runRelics.speed!=1)throw new Exception("Unequip retained curse or combo");for(int type=6;type<=7;type++){DropBossRelic(type,pos,false);UpdateLoot(.1f);DropBossRelic(type,pos,false);UpdateLoot(.1f);}DropBossRelic(4,pos,true);DropBossRelic(4,pos,true);if(save.relicOwned!=255)throw new Exception("Boss-specific relic rewards incomplete");int coins=runCoins;DropBossRelic(4,pos,true);if(runCoins!=coins+20)throw new Exception("Duplicate boss reward failed");var json=JsonUtility.ToJson(save);var loaded=JsonUtility.FromJson<SaveData>(json);loaded.NormalizeRelics();if(loaded.relicOwned!=255||loaded.relicLoadouts[0]!=0||loaded.relicLoadouts[1]!=-1)throw new Exception("Relic persistence failed");for(int set=0;set<4;set++){var stats=BuildRelicStats(set*2,set*2+1);if(stats.set!=set||stats.power<=0||stats.received<=0)throw new Exception("Invalid relic set");}TryEquipRelic(0,2);TryEquipRelic(0,3);StartRun();if(Mathf.Abs(AttackRate-.88f)>.001f||Mathf.Abs(Area-1.15f)>.001f||Mathf.Abs(runRelics.received-1.012f)>.001f)throw new Exception("Glacial set and curse not applied");TryEquipRelic(0,4);TryEquipRelic(0,5);StartRun();if(maxHp!=80||Mathf.Abs(Power-1.38f)>.001f||Mathf.Abs(runRelics.dragon-1.5f)>.001f||Mathf.Abs(AttackRate-.9f)>.001f)throw new Exception("Igneous set and curse not applied");TryEquipRelic(0,6);TryEquipRelic(0,7);StartRun();if(maxHp!=140||Mathf.Abs(Speed-3.41f)>.001f||Mathf.Abs(runRelics.enemySpeed-1.2f)>.001f||Mathf.Abs(runRelics.regen-.7f)>.001f)throw new Exception("Sovereign set and curse not applied");hp=50;regenTimer=1.01f;Tick(.001f);if(Mathf.Abs(hp-50.85f)>.01f)throw new Exception("Relic regeneration not applied");UnequipRelic(0,0);StartRun();AnimateHero(.1f,Vector2.zero);if(hero.sprite!=ArtBank.Hero(heroIndex))throw new Exception("Unequipping armor did not restore base outfit");save.relicOwned=0;StartElementTraining();DropBossRelic(3,pos,false);if(CollectRelic(0)||save.relicOwned!=0||runArmor!=-1)throw new Exception("Training granted/equipped relic");save=new SaveData{relicOwned=1,relicLoadouts=new[]{7,0,0,0,9,-1}};save.NormalizeRelics();if(save.relicLoadouts[0]!=-1||save.relicLoadouts[1]!=-1||save.relicLoadouts[4]!=-1)throw new Exception("Invalid save not sanitized");for(int armor=0;armor<4;armor++)for(int character=0;character<6;character++)for(int frame=0;frame<6;frame++){var outfit=ArtBank.ArmoredHero(character,armor*2,frame);if(outfit==null||!outfit.name.StartsWith("equipment-body-"))throw new Exception("Missing equipped outfit frame");}for(int id=0;id<8;id++)if(ArtBank.Relic(id)==null)throw new Exception("Missing relic asset "+id);save=account;heroIndex=oldHero;selectedCurse=oldCurse;selectedDragon=oldDragon;verifying=oldVerify;ReturnMenu();return "Relics: boss-specific ground drops/pickup, final-boss reward, duplicate coins, ownership/equip, per-hero loadouts, curses, sets, actual damage reduction, unequip/reset, JSON/migration, training isolation, eight item assets and 120 outfit poses across all six heroes PASS.";}
